PTX_SOURCE = r'''
.version 7.2
.target sm_80
.address_size 64

.visible .entry mse_kernel(
    .param .u64 __pred_ptr,
    .param .u64 __targ_ptr,
    .param .u64 __out_ptr,
    .param .u64 __sum_ptr,
    .param .u64 __cnt_ptr,
    .param .u64 __N
)
{
    // -------------------------------------------------
    // registers
    // -------------------------------------------------
    .reg .u64   %pred_ptr, %targ_ptr, %out_ptr, %sum_ptr, %cnt_ptr, %N;
    .reg .u32   %tid, %bid, %bdim, %gdim;
    .reg .u64   %idx, %stride;
    .reg .f16   %f_pred, %f_targ, %f_out;
    .reg .f32   %pred_f32, %targ_f32, %diff, %sq, %invN, %contrib, %sum_val;
    .reg .s32   %block_done;
    .reg .pred  %p0, %p1, %p2, %p3, %p4;

    // -------------------------------------------------
    // load parameters
    // -------------------------------------------------
    ld.param.u64 %pred_ptr, [__pred_ptr];
    ld.param.u64 %targ_ptr, [__targ_ptr];
    ld.param.u64 %out_ptr , [__out_ptr ];
    ld.param.u64 %sum_ptr , [__sum_ptr ];
    ld.param.u64 %cnt_ptr , [__cnt_ptr ];
    ld.param.u64 %N       , [__N       ];

    // -------------------------------------------------
    // thread / block ids
    // -------------------------------------------------
    mov.u32 %tid, %tid.x;
    mov.u32 %bid, %ctaid.x;
    mov.u32 %bdim, %ntid.x;
    mov.u32 %gdim, %nctaid.x;

    // -------------------------------------------------
    // pre‑compute stride = blockDim * gridDim
    // -------------------------------------------------
    mul.lo.u32 %stride, %bdim, %gdim;          // stride fits in 32‑bits (<= 2^31)

    // -------------------------------------------------
    // compute 1/N as float32 (approx reciprocal is fine)
    // -------------------------------------------------
    cvt.f32.u64 %invN, %N;
    mov.f32 %invN, 0f3f800000;                 // 1.0f
    rcp.approx.f32 %invN, %invN;               // invN = 1.0 / N

    // -------------------------------------------------
    // compute global starting index for this thread
    // -------------------------------------------------
    mad.lo.u32 %idx, %bid, %bdim, %tid;        // idx = bid*bdim + tid

LOOP:
    // if (idx >= N) break
    setp.ge.u64 %p0, %idx, %N;
    @%p0 bra END_LOOP;

    // load pred[idx] (fp16)
    mul.wide.u32 %r0, %idx, 2;                // byte offset = idx*2
    add.u64 %r0, %pred_ptr, %r0;
    ld.global.nc.f16 %f_pred, [%r0];

    // load targ[idx] (fp16)
    add.u64 %r1, %targ_ptr, %r0;
    ld.global.nc.f16 %f_targ, [%r1];

    // convert to fp32
    cvt.f32.f16 %pred_f32, %f_pred;
    cvt.f32.f16 %targ_f32, %f_targ;

    // diff = pred - targ
    sub.f32 %diff, %pred_f32, %targ_f32;

    // sq = diff * diff
    mul.f32 %sq, %diff, %diff;

    // contribution = sq * invN   (each thread adds its fractional part)
    mul.f32 %contrib, %sq, %invN;

    // atomic add contribution to global sum (float32)
    atom.global.add.f32 %sum_val, [%sum_ptr], %contrib;

    // idx += stride
    add.u64 %idx, %idx, %stride;
    bra LOOP;

END_LOOP:
    // -------------------------------------------------
    // signal block completion
    // -------------------------------------------------
    atom.global.add.u32 %block_done, [%cnt_ptr], 1;

    // -------------------------------------------------
    // spin‑wait until all blocks have signaled
    // -------------------------------------------------
WAIT_ALL:
    ld.global.u32 %block_done, [%cnt_ptr];
    setp.lt.u32 %p1, %block_done, %gdim;
    @%p1 bra WAIT_ALL;

    // -------------------------------------------------
    // thread (0,0) writes final result (mean) as fp16
    // -------------------------------------------------
    setp.eq.u32 %p2, %tid, 0;
    setp.eq.u32 %p3, %bid, 0;
    @%p2 @%p3 {
        ld.global.f32 %sum_val, [%sum_ptr];
        cvt.rn.f16.f32 %f_out, %sum_val;
        st.global.f16 [%out_ptr], %f_out;
    }

    ret;
}
'''

class ModelNew:
    def __init__(self):
        # load PTX module
        self.module = ptx_load(PTX_SOURCE)

    def __call__(self, predictions, targets):
        # allocate auxiliary buffers on the same device as inputs
        N = predictions.numel()
        device = predictions.device

        # output scalar (fp16)
        out = torch.empty((), dtype=torch.float16, device=device)

        # auxiliary buffers: sum (float32) and counter (int32)
        sum_buf = torch.zeros((), dtype=torch.float32, device=device)
        cnt_buf = torch.zeros((), dtype=torch.int32, device=device)

        # launch configuration
        threads_per_block = 256
        blocks = (N + threads_per_block - 1) // threads_per_block

        args = [
            predictions.data_ptr(),
            targets.data_ptr(),
            out.data_ptr(),
            sum_buf.data_ptr(),
            cnt_buf.data_ptr(),
            N
        ]

        ptx_launch(self.module, "mse_kernel", (blocks, 1, 1), (threads_per_block, 1, 1), args)

        return out
